  },
  computed: {
    selectedPractice() { return this.practices[this.activePractice] },
    filteredCourses() { return this.scheduleFilter === '全部' ? this.courses : this.courses.filter(course => course.type === this.scheduleFilter) },
    priceTable() {
      return this.pricePlans.map(plan => ({
        zh: plan.zh,
        en: plan.en,
        total: this.formatAmount(plan.amount, 0),
        deposit: this.formatAmount(plan.amount * 0.15, 2)
      }))
    }
  },
  mounted() {
    this._previousOverflow = ''
    this._returnFocus = null
    this._scrollFrame = null
    this._scrollHandler = () => {
      if (this._scrollFrame !== null) return
      this._scrollFrame = window.requestAnimationFrame(() => {
        this._scrollFrame = null
        this.updateActiveSection()
      })
    }
    this._keyHandler = event => {
      if (event.key === 'Escape') {
        if (this.modal) this.closeModal()
        if (this.menuOpen) {
          this.closeMenu()
          const button = this.$el.querySelector('.menu-toggle')
          if (button) button.focus()
        }
      }
    }
    window.addEventListener('scroll', this._scrollHandler, { passive: true })
    window.addEventListener('keydown', this._keyHandler)
    try {
      const saved = window.localStorage.getItem('xinan-lang')
      if (saved === 'zh' || saved === 'en') this.lang = saved
    } catch (error) {
      // localStorage may be unavailable under file:// or privacy modes.
    }
    document.documentElement.lang = this.lang === 'en' ? 'en' : 'zh-CN'
    this.updateDocumentTitle()
    this.updateActiveSection()
  },
  beforeDestroy() {
    window.removeEventListener('scroll', this._scrollHandler)
    window.removeEventListener('keydown', this._keyHandler)
    if (this._scrollFrame !== null) window.cancelAnimationFrame(this._scrollFrame)
    if (this.modal) document.body.style.overflow = this._previousOverflow
  },
  methods: {
    tx(zh, en) { return this.lang === 'en' ? en : zh },
    pick(item, key) { return this.lang === 'en' ? item[key + 'En'] : item[key] },
    formatAmount(value, digits) { return value.toLocaleString('en-US', { minimumFractionDigits: digits, maximumFractionDigits: digits }) },
    updateDocumentTitle() {
      document.title = this.lang === 'en'
        ? 'Xin’an Zen Temple · Let go of the noise'
        : '心安禅寺 · 放下纷扰，遇见心安'
    },
    setLang(value) {
      this.lang = value
      document.documentElement.lang = value === 'en' ? 'en' : 'zh-CN'
      this.updateDocumentTitle()
      try { window.localStorage.setItem('xinan-lang', value) } catch (error) { /* ignore storage restrictions */ }
    },
    closeMenu() { this.menuOpen = false },
    updateActiveSection() {
      let current = 'home'
      this.navigation.forEach(item => {
        const section = document.getElementById(item.id)
        if (section && section.getBoundingClientRect().top <= 160) current = item.id
      })
      this.activeSection = current
    },
    changePracticeTab(event, index) {
      let next = index
      if (event.key === 'ArrowRight') next = (index + 1) % this.practices.length
      else if (event.key === 'ArrowLeft') next = (index + this.practices.length - 1) % this.practices.length
      else if (event.key === 'Home') next = 0
      else if (event.key === 'End') next = this.practices.length - 1
      else return
      event.preventDefault()
      this.activePractice = next
      this.$nextTick(() => document.getElementById('practice-tab-' + this.practices[next].id).focus())
    },
    showModal(type) {
      this._returnFocus = document.activeElement
      this._previousOverflow = document.body.style.overflow
      document.body.style.overflow = 'hidden'
      this.modal = type
      this.$nextTick(() => {
        const panel = this.$refs.modal
        if (panel) {
          const first = panel.querySelector(type === 'registration' ? 'input' : 'button')
          ;(first || panel).focus()
        }
      })
    },
    openRegistration() {
      this.closeMenu()
      this.registrationText = ''
      this.copyStatus = ''
      this.showModal('registration')
    },
    openPhoto(index) { this.photoIndex = index; this.showModal('photo') },
    closeModal() {
      this.modal = null
      document.body.style.overflow = this._previousOverflow
      this.$nextTick(() => {
        if (this._returnFocus && this._returnFocus.isConnected) this._returnFocus.focus()
      })
    },
    trapFocus(event) {
      const elements = this.$refs.modal.querySelectorAll('button, a[href], input, select, textarea, [tabindex="0"]')
      const first = elements[0]
      const last = elements[elements.length - 1]
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() }
    },
    prepareRegistration() {
      const data = this.registration
      const levelZh = { beginner: '初级', intermediate: '中级', advanced: '高级' }
      const levelEn = { beginner: 'Beginner', intermediate: 'Intermediate', advanced: 'Advanced' }
      const level = this.lang === 'en' ? levelEn[data.trainingLevel] : levelZh[data.trainingLevel]
      const period = (data.periodFrom || '—') + (this.lang === 'en' ? ' – ' : ' 至 ') + (data.periodTo || '—')
      const message = data.message || (this.lang === 'en' ? 'Not provided' : '未填写')
      this.registrationText = this.lang === 'en'
        ? [
            'Xin’an Zen Temple Registration Form',
            'Full Name: ' + data.fullName,
            'Email Address: ' + data.email,
            'Phone Number: ' + data.phone,
            'Country of Residence: ' + data.country,
            'Intended Training Period: ' + period,
            'Training Level: ' + level,
            'Message or Additional Questions: ' + message
          ].join('\n')
        : [
            '心安禅寺报名表',
            '姓名：' + data.fullName,
            '电子邮箱：' + data.email,
            '电话号码：' + data.phone,
            '居住国家：' + data.country,
            '计划学习时间：' + period,
            '训练水平：' + level,
            '留言或其他问题：' + message
          ].join('\n')
      this.copyStatus = ''
    },
    copyRegistration() {
      // Promise syntax avoids adding an async runtime dependency to this older Vue 2 project.
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(this.registrationText).then(() => {
          this.copyStatus = 'copied'
        }).catch(() => this.copyRegistrationFallback())
      } else this.copyRegistrationFallback()
    },
    copyRegistrationFallback() {
      const field = this.$refs.copyText
      if (!field) return
      field.focus()
      field.select()
      try {
        this.copyStatus = document.execCommand('copy') ? 'copied' : 'manual'
      } catch (error) {
        this.copyStatus = 'manual'
      }
    }
  }
}
</script>

